corrected_code:
const messageResolvers = {
  Subscription: {
    directMessageReceived: {
      subscribe: async (root, { conversationId }, context) => {
        if (!context.user) throw new Error('Unauthenticated');
        const isMember = await ConversationMember.findOne({
          where: { conversationId, userId: context.user.id }
        });
        if (!isMember) throw new Error('Unauthorized to subscribe to this conversation');
        return pubsub.asyncIterator([`CONVERSATION_${conversationId}_MESSAGES`]);
      },
      resolve: (payload) => payload.message
    }
  }
};
